body:has(.modal.ui-win.on:not(#settingsmodal):not(#welcomemodal)) #topright, body:has(#hub.on) #topright{ right:90px !important; }
/* v28.xx (cw-cardmargin), his Q43 (2026-10-18): windows are "a centred card with an X in the corner ... nearly the entire screen". The shop, codex, trophies, fashion, mainframe, gamble, bar, terms, party and sector windows were a slab 14 px from the screen edge with a clipped corner tick. Now the card is 90 percent of the screen both ways (5 percent margin all round, the scrim shows around it), 4 px corners, no corner tick, no accent tab, and the X and the credits readout sit inside its top right. Style guide: Window, 90 x 90. */
#root .modal.ui-win:not(#settingsmodal):not(#welcomemodal){ padding:calc(5vh + 22px) calc(5vw + 22px); }
#root .modal.ui-win:not(#settingsmodal):not(#welcomemodal)::before{ inset:5vh 5vw; border-radius:4px; clip-path:none; border-color:var(--ui-line-hi); background:var(--ui-bg); }
#root .modal.ui-win:not(#settingsmodal):not(#welcomemodal) > .ui-foot > .ui-back{ top:calc(5vh + 12px); right:calc(5vw + 16px); }
body:has(.modal.ui-win.on:not(#settingsmodal):not(#welcomemodal)) #topright{ top:calc(5vh + 14px) !important; right:calc(5vw + 82px) !important; }

check:
{v:'VER',what:'the shop window is a card with a 5 percent margin on every side (90 x 90 of the screen), and its X sits inside the card',
 run:function(){
   if(!(window.__hubEnter&&window.__showScreen)) return 'SKIP: this fixture cannot walk the Undercroft';
   var bad=[], m, cs, tw=window.innerWidth, th=window.innerHeight, b, q;
   try{
     __topClear(); __cleanProfile();
     G=null; keys={}; __showScreen('hub'); __hubEnter();
     openTrader('buy');
     m=document.getElementById('tradermodal'); if(!m) return 'no shop window';
     cs=getComputedStyle(m,'::before');
     var t=parseFloat(cs.top), l=parseFloat(cs.left), r=parseFloat(cs.right), bo=parseFloat(cs.bottom);
     if(!(Math.abs(t-th*0.05)<=3)) bad.push('the card top margin is '+Math.round(t)+' px, not 5 percent ('+Math.round(th*0.05)+')');
     if(!(Math.abs(bo-th*0.05)<=3)) bad.push('the card bottom margin is '+Math.round(bo)+' px, not 5 percent');
     if(!(Math.abs(l-tw*0.05)<=3)) bad.push('the card left margin is '+Math.round(l)+' px, not 5 percent ('+Math.round(tw*0.05)+')');
     if(!(Math.abs(r-tw*0.05)<=3)) bad.push('the card right margin is '+Math.round(r)+' px, not 5 percent');
     b=document.getElementById('closetrader'); q=b?b.getBoundingClientRect():null;
     if(!q||!(q.width>8)) bad.push('the shop X has no box');
     else if(!(q.right<=tw*0.95&&q.left>tw*0.8&&q.top>=th*0.05-1)) bad.push('the shop X is not inside the card top right ('+Math.round(q.left)+','+Math.round(q.top)+','+Math.round(q.right)+')');
     if(b) b.click();
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ __topClear(); }catch(_c){} }
   return bad.length?bad.join('; '):null; }},
